function plot_structure_comparison(root)
% Figures from actual algebra, packet replay, flow, and physical recordings.
if nargin<1,root=fileparts(fileparts(mfilename('fullpath')));end
out=fullfile(root,'assets','result');d=jsondecode(fileread(fullfile(out,'structure_benchmarks.json')));set(groot,'defaultFigureVisible','off');
f=figure('Color','w','Position',[40,40,1600,1000]);tiledlayout(2,3,'TileSpacing','compact');
nexttile;r=d.arithmetic.scan.fixedN;stem([r.k],[r.blindDimension],'filled');grid on;xlabel('Service order k');ylabel('dim ker R_k');title('Fixed N=60: arithmetic blind dimensions');
nexttile;r=d.arithmetic.scan.fixedK;stem([r.N],[r.blindDimension],'filled');grid on;xlabel('Population N');ylabel('dim ker R_{21}');title('Fixed k=21: population changes the quotient');
nexttile;r=d.arithmetic.joint;g=zeros(numel(r),2);labels=cell(1,numel(r));for i=1:numel(r),g(i,:)=[r(i).single.commonBlindDimension,r(i).complement.commonBlindDimension];labels{i}=sprintf('%d,%d',r(i).single.N,r(i).single.k);end;bar(g);set(gca,'XTickLabel',labels);ylabel('Common blind dimension');xlabel('(N,k)');legend({'Service only','Adjacent complement'},'Location','best');title('Joint changes: classification, not a robot run');grid on;
nexttile;r=d.nestedGeometry.orders;plot([r.k],[r.sectorCost],'--',[r.k],[r.sectorBestPhaseCost],'-o',[r.k],[r.voronoiCost],'-s','LineWidth',1.3);grid on;xlabel('Service order k');ylabel('Assigned H');title('Same 30 fixed sites: geometric rank effect');legend({'Cyclic phase 0','Best-phase cyclic','Nearest-k'},'Location','best');
nexttile;r=d.nestedGeometry.population;plot([r.N],[r.sectorCost],'--',[r.N],[r.sectorBestPhaseCost],'-o',[r.N],[r.voronoiCost],'-s','LineWidth',1.3);grid on;xlabel('Nested population N');ylabel('Assigned H');title('Same surviving sites; k=7, no motion');
nexttile;hold on;labels={'Single order','Complement','Persistent switching'};for i=1:3,r=d.arithmetic.recovery(i).rows;semilogy([r.epoch],max([r.massError],1e-15),'LineWidth',1.5);end;set(gca,'YScale','log');grid on;xlabel('Boundary epoch');ylabel('Relative basic-mass error');title('50 to 49, k=7: explicit spectral repair');legend(labels,'Location','best');
sgtitle('Algebra and geometry are different experiments: fixed sites, arithmetic modes, and mass control');finish(f,out,'S01_arithmetic_and_repair');
f=figure('Color','w','Position',[40,40,1600,1000]);tiledlayout(2,3,'TileSpacing','compact');r=findcase(d,'small_ring');names={'Cyclic moments','Cached Voronoi','Full snapshot'};keys={'sector','voronoi','snapshot'};
nexttile;hold on;for j=1:3,v=arrayfun(@(a)a.protocols.(keys{j}).totalByteHops,r.rows);plot([r.rows.epoch],v/1000,'LineWidth',1.5);end;grid on;xlabel('Common replay epoch');ylabel('Cumulative byte-hops / 1000');title('N=18,k=3: identical sector-motion trace');legend(names,'Location','best');
nexttile;p=findcase(d,'small_path');hold on;for j=1:3,v=arrayfun(@(a)a.protocols.(keys{j}).rounds,p.rows);plot([p.rows(2:end).epoch],v(2:end),'LineWidth',1.4);end;grid on;xlabel('Common replay epoch');ylabel('Rounds, excluding startup epoch');title('Cut carrier path: fewer bytes need not mean fewer rounds');
nexttile;selected={'small_ring','small_path','large_order','known_frozen','radio_connected'};v=zeros(1,numel(selected));for i=1:numel(selected),p=findcase(d,selected{i});v(i)=p.cyclicToBestRecordedVorRatio;end;bar(v);yline(1,'k--');set(gca,'XTickLabel',{'Ring','Path','Large k','Frozen','Radio'});ylabel('Cyclic / best recorded Vor byte cost');title('Conditional ratios; within-case durations differ');grid on;
nexttile;selected={'small_n12','small_ring','larger_n30'};v=zeros(3,3);for i=1:3,p=findcase(d,selected{i});for j=1:3,v(i,j)=mean(arrayfun(@(a)a.protocols.(keys{j}).byteHops,p.rows(2:end)));end;end;bar(v/1000);set(gca,'XTickLabel',{'N=12','N=18','N=30'});ylabel('Mean later byte-hops / 1000');title('Fixed k=3: measured population scaling');grid on;
nexttile;v=r.rows(end).protocols.snapshot.totalByteHops;bar([v,v]/1000);set(gca,'XTickLabel',{'Cyclic','Voronoi'});ylabel('Given full-snapshot byte-hops / 1000');title('Shared safety snapshot: same existing information');grid on;
nexttile;budgets=[500,1000,2000];v=zeros(3,3);for i=1:3,for j=1:3,v(i,j)=sum(arrayfun(@(a)a.protocols.(keys{j}).totalRounds<=budgets(i),r.rows));end;end;bar(v);set(gca,'XTickLabel',{'500','1000','2000'});xlabel('Total communication-round budget');ylabel('Complete prefix epochs admitted');title('Budget audit of a prerecorded trace');grid on;
sgtitle('Actual routed packets, including requests/replies and startup; responsibility-layer scope is explicit');finish(f,out,'S02_protocol_replay');
f=figure('Color','w','Position',[40,40,1600,1000]);tiledlayout(2,3,'TileSpacing','compact');
nexttile;r=d.faults.rows;plot([r.failedId],[r.sectorTurnover],'-o',[r.failedId],[r.voronoiTurnover],'-s','LineWidth',1.2);grid on;xlabel('Failed physical ID');ylabel('New membership mass / k');title('Fixed positions, N=22,k=7: single-fault exposure');legend({'Equal cyclic','Nearest-k'},'Location','best');
nexttile;r=d.arithmetic.multiFaults;bar([r.blindResidue]);set(gca,'XTickLabel',{'13+14','13+25','13+28','1+50'});ylabel('Relative blind projection');title('Same N=48,k=6,d=6; different fault amplitudes');grid on;
nexttile;r=d.capacity;v=zeros(numel(r),3);for i=1:numel(r),v(i,:)=[r(i).voronoiCost,r(i).cost,r(i).cyclicCost];end;bar(v);set(gca,'XTickLabel',{'Ring 18,3','Ring 22,7','Random 18,3'});ylabel('Same-position assigned H');title('Capacity-aware comparison and best cyclic phase');legend({'Nearest-k','Capacity optimum','Best-phase cyclic'},'Location','best');grid on;
nexttile;r=d.capacity;v=zeros(numel(r),3);for i=1:numel(r),v(i,:)=[r(i).voronoiLoadError,r(i).loadError,r(i).cyclicLoadError];end;bar(v);set(gca,'XTickLabel',{'Ring 18,3','Ring 22,7','Random 18,3'});ylabel('Relative RMS load error');title('Geometric capacity optimization also balances loads');grid on;
nexttile;r=d.matchedPhase;v=[r(1).sector.final.pathLength,r(2).sector.final.pathLength,r(2).voronoi.final.pathLength];bar(v);set(gca,'XTickLabel',{'Cyclic phase 0','Aligned cyclic','Voronoi'});ylabel('Total physical path length');title('Same robots and map: phase affects travel');grid on;
nexttile;v=[r(1).sector.final.effort,r(2).sector.final.effort,r(2).voronoi.final.effort];bar(v);set(gca,'XTickLabel',{'Cyclic phase 0','Aligned cyclic','Voronoi'});ylabel('Integral sum ||u||^2 dt');title('Applied SI velocity effort, not physical energy');grid on;
sgtitle('Predictable exposure and local algebra come with a geometric tradeoff; exclusive optimality is not claimed');finish(f,out,'S03_faults_and_capacity');fprintf('Completed three structural comparison figures.\n');
end
function r=findcase(d,name),r=d.protocols(find(strcmp({d.protocols.name},name),1));end
function finish(f,out,name),set(findall(f,'Type','axes'),'FontSize',10);exportgraphics(f,fullfile(out,[name,'.png']),'Resolution',150);close(f);end
